/* Trade drafts are UI JSON; accepted offers commit atomically to the career. */
let tradeDraft=null,tradeCenterBusy=false;
function currentTradeDraft(){const key=activeSaveId+':'+state.year;if(!tradeDraft||tradeDraft.key!==key)tradeDraft={key,club:state.teams.find(t=>t.id!==controlledTeamId()).id,out:[],into:[],cash:0,reasoning:'',status:'Pending'};return tradeDraft}
function tcChange(key,value){const d=currentTradeDraft();if(key==='club'){d.club=Number(value);d.into=[];d.inPicks=[]}else if(key==='cash')d.cash=Math.max(0,Math.min(10,Number(value)||0));else d.reasoning=String(value).slice(0,2000);d.status='Pending';render()}
function tcPlayer(side,id){const d=currentTradeDraft(),club=side==='out'?team():state.teams[d.club];if(!club?.roster.some(p=>p.id===id))return;d[side]=d[side].includes(id)?d[side].filter(x=>x!==id):[...d[side],id];d.status='Pending';render();if(side==='into'&&d.into.includes(id))saveGMTask(1)}
function tcValue(p,club){return tradePlayerValue(p,club)}
function evaluateFairness(outgoing,incoming,cash,club=state.teams[currentTradeDraft().club]){return tradeProposalAssessment(team(),club,outgoing,incoming,cash,selectedTradePicks('outPicks',team()),selectedTradePicks('inPicks',club),{human:true,suggest:true})}
function tradeCenterModel(){const d=currentTradeDraft(),club=state.teams[d.club]||state.teams.find(t=>t.id!==controlledTeamId()),out=team().roster.filter(p=>d.out.includes(p.id)),incoming=club.roster.filter(p=>d.into.includes(p.id)),delta=out.reduce((s,p)=>s+p.salary,0)-incoming.reduce((s,p)=>s+p.salary,0),fair=evaluateFairness(out,incoming,d.cash,club),ownPay=payroll()+(wnbaEnabled()?0:financeDead(team())),otherPay=ownerPayroll(club)+(wnbaEnabled()?0:financeDead(club)),errors=[];
 if(club.id===controlledTeamId()||expansionPendingSeason(club))errors.push('Select an eligible trade partner.');const outPicks=selectedTradePicks('outPicks',team()),inPicks=selectedTradePicks('inPicks',club);if(!out.length&&!outPicks.length||!incoming.length&&!inPicks.length)errors.push('Select at least one asset on each side.');errors.push(...tradeLegality(team(),club,out,incoming,d.cash,outPicks,inPicks));if(outPicks.length!==(d.outPicks||[]).length||inPicks.length!==(d.inPicks||[]).length)errors.push('A selected draft pick is no longer available.');if(out.length!==d.out.length||incoming.length!==d.into.length)errors.push('A selected player has moved teams.');if(tradeDeadlinePassed())errors.push('Trading is closed until the championship is complete.');if(d.cash>financeFor().cash)errors.push('Insufficient cash reserves.');for(const [c,count,pay] of [[team(),team().roster.length-out.length+incoming.length,ownPay-delta],[club,club.roster.length-incoming.length+out.length,otherPay+delta]]){if(count<rosterMinimum()||count>rosterMaximum())errors.push(c.city+' must retain '+rosterMinimum()+'–'+rosterMaximum()+' players.');if(!wnbaEnabled()&&pay>financeRosterLimit(c)+.00001)errors.push(c.city+' would exceed the roster spending limit.');}
 const top=roster=>roster.slice().sort((a,b)=>b.ovr-a.ovr).slice(0,5).reduce((s,p)=>s+p.ovr,0)/5,projected=team().roster.filter(p=>!d.out.includes(p.id)).concat(incoming),impact=top(projected)-top(team().roster),owner=ownerFor(team()),ownerReaction=owner.type==='penny'?Math.sign(delta):Math.sign(impact),fanReaction=Math.round(Math.max(-3,Math.min(3,impact))),chemistryChange=out.length?Math.max(-5,Math.min(5,Math.round((coachFit({...team(),roster:projected})-coachFit(team()))/2)-Math.min(3,out.length))):0;
 return {deadline:scheduleDate(seasonMilestones().deadline).toISOString().slice(0,10),daysRemaining:Math.max(0,seasonMilestones().deadline-state.day),teamsInvolved:[team().city+' '+team().name,club.city+' '+club.name],tradeOffer:{outgoingPicks:outPicks,incomingPicks:inPicks,outgoingPlayers:out.map(tcPlayerJSON),incomingPlayers:incoming.map(tcPlayerJSON),cash:d.cash,capImpact:(delta>=0?'+':'')+delta.toFixed(1)+'M',fairnessScore:fair.score,status:d.status},capSpace:salaryCap()-ownPay,capLimit:financeRosterLimit(),salaryCap:salaryCap(),ownerMood:owner.patience,coachPreference:coachFor(team()).system+' · '+coachFor(team()).focus,tradeHistory:displayTradeHistory(5),decisionLogLink:'/gm-office/decision-log',out,incoming,outPicks,inPicks,club,delta,fair,errors,ownPay,otherPay,projectedPay:ownPay-delta,impact,ownerReaction,fanReaction,chemistryChange};
}
function tcPlayerJSON(p){return {id:p.id,name:p.name,pos:p.pos,ovr:p.ovr,salary:p.salary,age:p.age,contractYears:Math.max(1,(p.contractThrough??state.year)-state.year+1)}}
function addTradeOffer(offer){const d=currentTradeDraft();if(!Number.isInteger(offer.club)||offer.club===controlledTeamId()||!state.teams[offer.club]||expansionPendingSeason(state.teams[offer.club]))throw new Error('Invalid trade partner');d.club=offer.club;d.outPicks=[...new Set(offer.outgoingPickKeys||[])];d.inPicks=[...new Set(offer.incomingPickKeys||[])];d.out=[...new Set(offer.outgoingPlayerIds)];d.into=[...new Set(offer.incomingPlayerIds)];d.cash=Math.max(0,Math.min(10,Number(offer.cash)||0));d.reasoning=String(offer.reasoning||'').slice(0,2000);d.status='Pending';render()}
function updateCapSpace(club){financeSync(club);if(club.id===controlledTeamId())decisionState().payroll={amount:payroll()+financeDead(club),capSpace:salaryCap()-payroll()-financeDead(club)}}
function recordTradeToDecisionLog(m){return addDecision({type:'Trade',description:'Traded '+[...m.out.map(p=>p.name),...m.outPicks.map(tradePickLabel)].join(', ')+' to '+m.club.city+' for '+[...m.incoming.map(p=>p.name),...m.inPicks.map(tradePickLabel)].join(', ')+(m.tradeOffer.cash?' plus '+money(m.tradeOffer.cash)+' cash sent':''),reasoning:currentTradeDraft().reasoning||'Roster restructuring',players:[...m.out,...m.incoming].map(p=>({id:p.id,name:p.name})),immediateOutcome:{fanReaction:m.fanReaction,ownerReaction:m.ownerReaction,chemistryChange:m.chemistryChange,capChange:m.tradeOffer.capImpact}})}
function displayTradeHistory(limit=5){return (state.newsFeed?.items||[]).filter(n=>/acquires .*in exchange|trade completed/i.test(n.headline)).slice(0,limit).map(n=>({year:n.year,day:n.day,description:n.headline}))}
async function finalizeTradeCenter(){if(tradeCenterBusy||!ownerCanManage())return;const m=tradeCenterModel();if(m.errors.length)return toast(m.errors[0]);if(!m.fair.accepted){currentTradeDraft().status='Declined';render();return toast(m.fair.reasons.join(' '))}tradeCenterBusy=true;const before=copy(state);try{team().roster=team().roster.filter(p=>!m.out.includes(p)).concat(m.incoming);m.club.roster=m.club.roster.filter(p=>!m.incoming.includes(p)).concat(m.out);for(const p of [...m.out,...m.incoming]){resetPlayerSituation(p);p.moraleAdjustment=-6;lockTradedPlayer(p)}transferTradePicks(team(),m.club,m.outPicks,m.inPicks);for(const club of [team(),m.club]){if(club.rotationPlan)club.rotationPlan=rotationFromClub(club)}rotationDraft=null;if(m.tradeOffer.cash){financePost(financeFor(),'tradeCash',m.tradeOffer.cash,true);financePost(financeFor(m.club),'tradeCash',m.tradeOffer.cash)}tradeBlockRecordTrade(m);recordTradeToDecisionLog(m);updateCapSpace(team());updateCapSpace(m.club);say('Trade completed: '+team().city+' acquires '+[...m.incoming.map(p=>p.name),...m.inPicks.map(tradePickLabel)].join(', ')+' from '+m.club.city+' in exchange for '+[...m.out.map(p=>p.name),...m.outPicks.map(tradePickLabel)].join(', ')+'.');if(!await save()){state=before;return toast('Trade could not be saved. No changes applied.')}currentTradeDraft().out=[];currentTradeDraft().into=[];currentTradeDraft().cash=0;currentTradeDraft().outPicks=[];currentTradeDraft().inPicks=[];currentTradeDraft().status='Accepted';toast('Trade accepted and recorded in your Decision Log.')}catch(error){state=before;toast('Trade cancelled: '+error.message)}finally{tradeCenterBusy=false;render()}}
function openTradeDecisionLog(){officeTab='decisions';go('GM Office')}
function tcRosterCard(club,side){const d=currentTradeDraft();return `<section class="panel"><div class="panelhead"><h2>${side==='out'?'You Send':'You Receive'}</h2>${teamLogo(club)}</div><div class="tc-player-list">${club.roster.map(p=>`<article class="tc-player ${d[side].includes(p.id)?'selected':''}"><div class="tc-silhouette">${playerSilhouette()}</div><div><button class="namebutton" onclick="profile(${p.id})">${escapeHTML(p.name)}</button><small>${p.pos} · Age ${p.age} · ${ratingMarkup(p.ovr)} OVR</small><small>${money(p.salary)} / yr · ${tcPlayerJSON(p).contractYears} yrs</small>${tradeRestrictionText(p)?`<small>${escapeHTML(tradeRestrictionText(p))}</small>`:''}</div><button aria-label="${d[side].includes(p.id)?'Remove':'Add'} ${escapeHTML(p.name)}" onclick="tcPlayer('${side}',${p.id})">${d[side].includes(p.id)?'Remove':'Add +'}</button></article>`).join('')}</div></section>`}
trades=function(){const d=currentTradeDraft(),m=tradeCenterModel(),tier=m.fair.score>=.9?'good':m.fair.score>=.7?'close':'poor';return `<div class="tc-page"><header class="panel tc-heading"><div><h2>Trade Center</h2><p>Negotiate, balance payroll, and reshape your roster.</p></div><strong>${tradeDeadlinePassed()?'Trade deadline passed':state.champion!==null?'Offseason trading open':m.daysRemaining+' days remaining'}<small>Deadline · ${m.deadline}</small></strong></header><div class="tc-toolbar"><label>Trade partner<select onchange="tcChange('club',this.value)">${state.teams.filter(t=>t.id!==controlledTeamId()).filter(t=>!expansionPendingSeason(t)).map(t=>`<option value="${t.id}" ${d.club===t.id?'selected':''}>${escapeHTML(t.city+' '+t.name)}</option>`).join('')}</select></label><span>Owner patience ${m.ownerMood}% · ${escapeHTML(m.coachPreference)}</span></div><div class="tc-layout"><div><div class="tc-mirrored">${tcRosterCard(team(),'out')}${tcRosterCard(m.club,'into')}${tradePickPanel(team(),'outPicks')}${tradePickPanel(m.club,'inPicks')}</div><section class="panel note"><label>Cash sent · ${money(d.cash)}<input type="range" min="0" max="10" step=".1" value="${d.cash}" aria-label="Cash sent in millions" onchange="tcChange('cash',this.value)"></label><small>Available reserves ${money(financeFor().cash)}</small><label>GM reasoning<textarea maxlength="2000" oninput="currentTradeDraft().reasoning=this.value">${escapeHTML(d.reasoning)}</textarea></label><div class="actions"><button class="primary" onclick="finalizeTradeCenter()" ${tradeCenterBusy||m.errors.length?'disabled':''}>Propose & finalize trade</button><button onclick="tradeDraft=null;render()">Clear offer</button></div><p role="status">${m.errors.map(escapeHTML).join(' ')||'Offer passes roster and payroll checks.'}</p></section></div><aside class="panel note tc-analysis"><h2>Trade Analysis</h2><strong class="tc-${tier}">Fairness · ${Math.round(m.fair.score*100)}%</strong><meter min="0" max="1" value="${m.fair.score}"></meter><p>100% means balanced value. AI acceptance also considers which team receives more value.</p><h3>Payroll after trade</h3><strong>${money(m.projectedPay)} / ${money(m.capLimit)}</strong><meter min="0" max="${m.capLimit}" value="${Math.min(m.capLimit,m.projectedPay)}"></meter><p title="Outgoing salaries minus incoming salaries. Cash does not create salary-cap room.">Cap impact ${m.tradeOffer.capImpact} · Cap space ${money(m.salaryCap-m.projectedPay)}<br>Partner payroll ${money(m.otherPay+m.delta)} / ${money(financeRosterLimit(m.club))}</p><h3>Projected lineup impact</h3><p>Top-five average OVR: ${m.impact>=0?'+':''}${m.impact.toFixed(1)}</p><meter min="-20" max="20" value="${Math.max(-20,Math.min(20,m.impact))}"></meter><h3>GM Insight</h3><p>Team mindset: ${m.fair.mindset}</p><p>${escapeHTML(coachFor(m.club).name)} values ${escapeHTML(coachFor(m.club).type)} players with a ${escapeHTML(coachFor(m.club).focus)} focus.</p><blockquote>${!m.out.length&&!m.outPicks.length||!m.incoming.length&&!m.inPicks.length?'Select assets to receive feedback.':escapeHTML(m.fair.feedback)}</blockquote><p>Value sent by partner: ${m.fair.sent.toFixed(1)} · Value received: ${m.fair.received.toFixed(1)} · Required: ${m.fair.required.toFixed(1)} (15% buffer)${m.fair.packagePenalty?'<br>Package discount: '+m.fair.packagePenalty.toFixed(1):''}</p>${m.fair.suggestedPick?'<button onclick="addTradeSweetener()">Add suggested pick</button>':''}<p>Owner reaction ${m.ownerReaction>=0?'+':''}${m.ownerReaction} · Fan sentiment ${m.fanReaction>=0?'+':''}${m.fanReaction} · Chemistry ${m.chemistryChange}<br><small>Preview applies only to completed trades. Failed offers have no penalty.</small></p><p>Status: ${d.status}</p></aside></div><section class="panel note"><h2>Recent league trades</h2>${m.tradeHistory.map(h=>`<p><small>${h.year??'Earlier'} · Day ${h.day??'—'}</small><br>${escapeHTML(h.description)}</p>`).join('')||'<p>No trades recorded yet.</p>'}<button onclick="openTradeDecisionLog()">GM History · Decision Log</button><p>Completed trades are recorded automatically with your reasoning.</p></section></div>`};
playerTradeAction=function(id){const c=playerContext(id);if(!c?.club)return;document.getElementById('profile').close();tradeDraft=null;const d=currentTradeDraft();if(c.own)d.out=[id];else{d.club=c.club.id;d.into=[id]}go('Trades')};
reviewGMProposal=function(id){const m=inboxStore().items.find(m=>m.id===id);if(!m||!proposalAvailable(m))return toast('This proposal is no longer available.');tradeDraft=null;const d=currentTradeDraft();Object.assign(d,{club:m.proposal.club,out:[m.proposal.out],into:[m.proposal.into],reasoning:'Responding to '+m.sender});go('Trades')};
